runCommand:
cat > /opt/patchgate/patchgate_install.py <<'PATCHGATE_EOF'
#!/usr/bin/env python3
"""Patchgate install-plan executor for Linux.

Runs inside the VM as root. Standard library only, so it works on any distribution
with Python 3.9+ (Amazon Linux 2023, RHEL 9, Ubuntu 22.04+). It never calls a cloud API:
everything it needs is in the install plan produced by `python -m patchgate compile`.

Exit codes: 0 success, 1 failure, 2 invalid input.
"""

from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import json
import logging
import os
import re
import shutil
import subprocess
import sys
import tarfile
import tempfile
import time
import urllib.request
from pathlib import Path
from typing import Any

LOG_DIR = Path("/var/log/patchgate")
STATE_DIR = Path("/var/lib/patchgate")
STATE_FILE = STATE_DIR / "state.json"
PLAN_FILE = STATE_DIR / "plan.json"  # last applied plan, re-used by drift runs
COMPLIANCE_FILE = STATE_DIR / "compliance.json"  # evidence: last result of every control
DRIFT_EVENT_FILE = STATE_DIR / "drift-event.json"  # picked up and published by the provider
DRIFT_INTERVALS = {"30m": 1800, "1h": 3600, "2h": 7200, "6h": 21600, "12h": 43200, "24h": 86400}
DRIFT_SLACK_SECONDS = 120  # schedulers fire slightly early/late

# "ansible" hardening engine (ADR 0007): a pinned runtime in its own venv; modules run on the
# system Python, which has the distribution's package-manager bindings.
PATCHGATE_HOME = Path("/opt/patchgate")
ANSIBLE_VENV = PATCHGATE_HOME / "ansible"
ANSIBLE_COLLECTIONS = PATCHGATE_HOME / "ansible-collections"
BASELINES_DIR = PATCHGATE_HOME / "baselines"
ANSIBLE_LOCK = Path(__file__).resolve().with_name("ansible-requirements.txt")
ANSIBLE_PYTHONS = ("python3.12", "python3.13", "python3.14", "python3")
# Task names look like "<role path> : 1.1.1.1 | PATCH | Ensure ..." in the JSON report.
CIS_ID = re.compile(r"(?:^|:\s+)\"?(\d+(?:\.\d+)+)\s*\|")
STATUS_RANK = {"compliant": 0, "remediated": 1, "non-compliant": 2, "failed": 3}
DOWNLOAD_TIMEOUT = 300
VALIDATE_ATTEMPTS = 5
VALIDATE_DELAY_SECONDS = 6

log = logging.getLogger("patchgate")


class InstallError(RuntimeError):
    pass


# ---------------------------------------------------------------- helpers


def run(cmd: list[str], *, env: dict[str, str] | None = None) -> None:
    log.info("$ %s", " ".join(cmd))
    proc = subprocess.run(  # noqa: S603 - commands are built from a reviewed catalog
        cmd, env=env, capture_output=True, text=True, check=False
    )
    for line in (proc.stdout + proc.stderr).splitlines():
        log.info("  %s", line)
    if proc.returncode != 0:
        raise InstallError(f"command failed ({proc.returncode}): {' '.join(cmd)}")


def run_script(script: str, label: str) -> None:
    with tempfile.NamedTemporaryFile("w", suffix=".sh", delete=False) as handle:
        handle.write(script)
        path = handle.name
    try:
        run(["/bin/bash", "-euo", "pipefail", path])
    except InstallError as exc:
        raise InstallError(f"{label} failed") from exc
    finally:
        os.unlink(path)


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def download(url: str, expected_sha256: str, dest: Path) -> Path:
    if not url.startswith("https://"):
        raise InstallError(f"refusing non-https source: {url}")
    log.info("downloading %s", url)
    with urllib.request.urlopen(url, timeout=DOWNLOAD_TIMEOUT) as response, dest.open("wb") as out:  # noqa: S310
        shutil.copyfileobj(response, out)
    actual = sha256_file(dest)
    if actual != expected_sha256:
        dest.unlink(missing_ok=True)
        raise InstallError(f"checksum mismatch for {url}: expected {expected_sha256}, got {actual}")
    log.info("checksum OK (%s)", actual)
    return dest


def detect_package_manager() -> str:
    for manager in ("dnf", "yum", "apt-get"):
        if shutil.which(manager):
            return manager
    raise InstallError("no supported package manager found (dnf, yum, apt-get)")


def packages_for(spec: dict[str, Any], manager: str) -> list[str]:
    packages: dict[str, list[str]] = spec["packages"]
    key = "apt" if manager == "apt-get" else "dnf"
    if key not in packages:
        raise InstallError(f"agent has no package list for {key}")
    return packages[key]


def install_packages(manager: str, names: list[str]) -> None:
    if manager == "apt-get":
        env = {**os.environ, "DEBIAN_FRONTEND": "noninteractive"}
        run(["apt-get", "update", "-q"], env=env)
        run(["apt-get", "install", "-y", "-q", *names], env=env)
    else:
        run([manager, "install", "-y", "-q", *names])


# ---------------------------------------------------------------- steps


def install_step(step: dict[str, Any], manager: str, workdir: Path) -> None:
    method = step["method"]
    if method == "package":
        install_packages(manager, packages_for(step, manager))
    elif method in ("rpm", "deb"):
        target = download(step["source"], step["sha256"], workdir / f"{step['agent']}.{method}")
        if method == "deb" and manager != "apt-get":
            raise InstallError(".deb packages require apt-get")
        if method == "rpm" and manager == "apt-get":
            raise InstallError(".rpm packages require dnf/yum")
        install_packages(manager, [str(target)])
    elif method == "script":
        run_script(step["script"], f"{step['agent']} script")
    else:
        raise InstallError(f"unsupported method on linux: {method}")
    if step.get("postInstall"):
        run_script(step["postInstall"], f"{step['agent']} postInstall")


def validate_step(step: dict[str, Any]) -> None:
    command = step.get("validate")
    if not command:
        return
    for attempt in range(1, VALIDATE_ATTEMPTS + 1):
        proc = subprocess.run(  # noqa: S603
            ["/bin/bash", "-c", command], capture_output=True, text=True, check=False
        )
        if proc.returncode == 0:
            log.info("validate OK: %s", step["agent"])
            return
        log.info("validate attempt %d/%d failed for %s", attempt, VALIDATE_ATTEMPTS, step["agent"])
        time.sleep(VALIDATE_DELAY_SECONDS)
    raise InstallError(f"validation failed for {step['agent']}: {command}")


def run_quiet(command: str) -> bool:
    proc = subprocess.run(  # noqa: S603
        ["/bin/bash", "-c", command], capture_output=True, text=True, check=False
    )
    return proc.returncode == 0


def apply_hardening(hardening: dict[str, Any] | None, mode: str) -> list[dict[str, str]]:
    """Run the profile's hardening engine and record evidence. Returns one result per control.

    Status: compliant | remediated | non-compliant (audit) | failed (remediation did not fix it).
    """
    if not isinstance(hardening, dict):  # absent, or "none" in plans from older catalogs
        return []
    engine = hardening.get("engine")
    if engine == "controls":
        results = run_controls(hardening, mode)
    elif engine == "ansible":
        results = run_ansible(hardening, mode)
    else:
        raise InstallError(f"unsupported hardening engine: {engine}")
    write_json(
        COMPLIANCE_FILE,
        {
            "engine": engine,
            "level": hardening.get("level") or hardening.get("baseline"),
            "mode": mode,
            "checkedAt": now_iso(),
            "controls": results,
        },
    )
    return results


def run_controls(hardening: dict[str, Any], mode: str) -> list[dict[str, str]]:
    results = []
    for control in hardening["controls"]:
        name = control["name"]
        if run_quiet(control["check"]):
            status = "compliant"
        elif mode == "audit":
            status = "non-compliant"
        else:
            try:
                run_script(control["remediate"], f"control {name}")
            except InstallError as exc:
                log.error("%s", exc)
            status = "remediated" if run_quiet(control["check"]) else "failed"
        log.info("control %-32s %s", name, status)
        results.append({"control": name, "cis": control.get("cis", ""), "status": status})
    return results


# ---------------------------------------------------------------- ansible engine


def python_for_ansible() -> str:
    for candidate in ANSIBLE_PYTHONS:
        path = shutil.which(candidate)
        if not path:
            continue
        version = subprocess.run(  # noqa: S603
            [path, "-c", "import sys; print(sys.version_info >= (3, 12))"],
            capture_output=True,
            text=True,
            check=False,
        ).stdout.strip()
        if version == "True":
            return path
    install_packages(detect_package_manager(), ["python3.12"])
    path = shutil.which("python3.12")
    if not path:
        raise InstallError("python3.12 is required for the ansible engine")
    return path


def ensure_ansible_runtime() -> Path:
    """Create (once per lock version) a venv with the hash-pinned Ansible runtime."""
    lock_digest = sha256_file(ANSIBLE_LOCK)
    marker = ANSIBLE_VENV / ".patchgate-lock"
    if marker.exists() and marker.read_text().strip() == lock_digest:
        return ANSIBLE_VENV / "bin"
    if ANSIBLE_VENV.exists():
        shutil.rmtree(ANSIBLE_VENV)
    run([python_for_ansible(), "-m", "venv", str(ANSIBLE_VENV)])
    pip = str(ANSIBLE_VENV / "bin" / "pip")
    run([pip, "install", "--quiet", "--require-hashes", "--only-binary", ":all:", "--no-deps",
         "-r", str(ANSIBLE_LOCK)])  # fmt: skip
    marker.write_text(lock_digest)
    return ANSIBLE_VENV / "bin"


def safe_extract(archive: Path, dest: Path) -> None:
    """Extract a tar.gz, rejecting absolute paths, '..', devices and links leaving dest."""
    dest = dest.resolve()
    with tarfile.open(archive, "r:gz") as tar:
        for member in tar.getmembers():
            target = (dest / member.name).resolve()
            if not str(target).startswith(str(dest) + os.sep) and target != dest:
                raise InstallError(f"unsafe path in archive: {member.name}")
            if member.isdev():
                raise InstallError(f"device file in archive: {member.name}")
            if member.issym() or member.islnk():
                base = dest if member.islnk() else target.parent
                link = (base / member.linkname).resolve()
                if not str(link).startswith(str(dest) + os.sep):
                    raise InstallError(f"link escaping archive: {member.name}")
        if hasattr(tarfile, "data_filter"):  # Python 3.12+ and recent 3.9-3.11 patch releases
            tar.extractall(dest, filter="data")
        else:
            tar.extractall(dest)  # noqa: S202 - members validated above


def ensure_baseline(hardening: dict[str, Any], bin_dir: Path, workdir: Path) -> Path:
    """Download and verify the baseline and its collections; returns the playbook path."""
    target = BASELINES_DIR / f"{hardening['baseline']}-{hardening['sha256'][:12]}"
    if not (target / ".patchgate-complete").exists():
        archive = download(hardening["source"], hardening["sha256"], workdir / "baseline.tar.gz")
        unpacked = workdir / "baseline"
        unpacked.mkdir()
        safe_extract(archive, unpacked)
        entries = list(unpacked.iterdir())
        root = entries[0] if len(entries) == 1 and entries[0].is_dir() else unpacked
        if target.exists():
            shutil.rmtree(target)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(root), str(target))
        for collection in hardening.get("collections", []):
            tarball = download(
                collection["source"], collection["sha256"], workdir / f"{collection['name']}.tar.gz"
            )
            run([str(bin_dir / "ansible-galaxy"), "collection", "install", "--no-deps", "--offline",
                 "--force", "-p", str(ANSIBLE_COLLECTIONS), str(tarball)])  # fmt: skip
        (target / ".patchgate-complete").write_text(now_iso())
    playbook: Path = (target / str(hardening["playbook"])).resolve()
    if not str(playbook).startswith(str(target.resolve()) + os.sep) or not playbook.exists():
        raise InstallError(f"playbook not found in baseline: {hardening['playbook']}")
    return playbook


def parse_ansible_results(report: dict[str, Any], mode: str) -> list[dict[str, str]]:
    """Map ansible.posix.json output to per-CIS-rule results (worst status per rule wins)."""
    rules: dict[str, dict[str, str]] = {}
    for play in report.get("plays", []):
        for task in play.get("tasks", []):
            name = str(task.get("task", {}).get("name", ""))
            match = CIS_ID.search(name)
            if not match:
                continue
            for host in task.get("hosts", {}).values():
                if host.get("skipped"):
                    continue
                if host.get("failed") or host.get("unreachable"):
                    status = "failed"
                elif host.get("changed"):
                    status = "non-compliant" if mode == "audit" else "remediated"
                else:
                    status = "compliant"
                cis = match.group(1)
                current = rules.get(cis)
                if current is None or STATUS_RANK[status] > STATUS_RANK[current["status"]]:
                    rules[cis] = {
                        "control": f"cis-{cis}",
                        "cis": cis,
                        "status": status,
                        "title": name[:160],
                    }
    return [rules[k] for k in sorted(rules, key=lambda c: [int(p) for p in c.split(".")])]


def failed_tasks(report: dict[str, Any]) -> list[str]:
    """Names and messages of failed tasks, including non-rule tasks such as prechecks."""
    failures = []
    for play in report.get("plays", []):
        for task in play.get("tasks", []):
            for host in task.get("hosts", {}).values():
                if host.get("failed") or host.get("unreachable"):
                    message = str(host.get("msg", ""))[:300]
                    failures.append(f"{task.get('task', {}).get('name', '?')}: {message}")
    return failures[:5]


def run_ansible(hardening: dict[str, Any], mode: str) -> list[dict[str, str]]:
    bin_dir = ensure_ansible_runtime()
    with tempfile.TemporaryDirectory(prefix="patchgate-ansible-") as tmp:
        playbook = ensure_baseline(hardening, bin_dir, Path(tmp))
        variables = Path(tmp) / "vars.json"
        variables.write_text(json.dumps(hardening.get("variables", {})))
        command = [str(bin_dir / "ansible-playbook"), "-i", "localhost,", "-c", "local",
                   str(playbook), "-e", f"@{variables}"]  # fmt: skip
        if mode == "audit":
            command.append("--check")
        env = {
            **os.environ,
            "ANSIBLE_COLLECTIONS_PATH": str(ANSIBLE_COLLECTIONS),
            "ANSIBLE_STDOUT_CALLBACK": "ansible.posix.json",
            "ANSIBLE_PYTHON_INTERPRETER": "/usr/bin/python3",
            "ANSIBLE_NOCOLOR": "1",
            "ANSIBLE_RETRY_FILES_ENABLED": "False",
        }
        log.info("$ %s", " ".join(command))
        proc = subprocess.run(  # noqa: S603
            command, env=env, capture_output=True, text=True, check=False, cwd=playbook.parent
        )
    try:
        report = json.loads(proc.stdout)
    except json.JSONDecodeError as exc:
        tail = (proc.stdout + proc.stderr)[-2000:]
        raise InstallError(
            f"ansible-playbook gave no JSON report (rc={proc.returncode}): {tail}"
        ) from exc
    results = parse_ansible_results(report, mode)
    counts = summarize(results)
    log.info("ansible baseline %s: %s (rc=%d)", hardening["baseline"], counts, proc.returncode)
    for result in results:
        if result["status"] in ("failed", "non-compliant"):
            log.info("rule %-12s %-13s %s", result["cis"], result["status"], result["title"])
    if proc.returncode != 0 and not counts.get("failed"):
        detail = "; ".join(failed_tasks(report)) or proc.stderr[-1500:]
        raise InstallError(f"ansible-playbook failed (rc={proc.returncode}): {detail}")
    return results


# ---------------------------------------------------------------- applications


def installed_version(manager: str, name: str) -> str | None:
    """Installed version of a package ("<version>-<release>" on rpm systems), or None."""
    if manager == "apt-get":
        command = ["dpkg-query", "-W", "-f=${Status}|${Version}", name]
    else:
        command = ["rpm", "-q", "--qf", "installed|%{VERSION}-%{RELEASE}", name]
    proc = subprocess.run(command, capture_output=True, text=True, check=False)  # noqa: S603
    if proc.returncode != 0:
        return None
    status, _, version = proc.stdout.strip().rpartition("|")
    if manager == "apt-get" and status != "install ok installed":
        return None
    return version or None


def version_matches(installed: str, wanted: str) -> bool:
    """'2.40.1' matches an installed '2.40.1-1.amzn2023'; a full version must match exactly."""
    return installed == wanted or installed.split("-")[0] == wanted


def package_spec(manager: str, name: str, version: str | None) -> str:
    if not version:
        return name
    return f"{name}={version}" if manager == "apt-get" else f"{name}-{version}"


def change_app(manager: str, action: str, name: str, version: str | None = None) -> None:
    env = {**os.environ, "DEBIAN_FRONTEND": "noninteractive"}
    spec = package_spec(manager, name, version)
    if manager == "apt-get":
        commands = {
            "install": ["apt-get", "install", "-y", "-q", "--allow-downgrades", spec],
            "upgrade": ["apt-get", "install", "-y", "-q", "--only-upgrade", name],
            "remove": ["apt-get", "remove", "-y", "-q", name],
        }
        if action != "remove":
            run(["apt-get", "update", "-q"], env=env)
    else:
        commands = {
            "install": [manager, "install", "-y", "-q", spec],
            "upgrade": [manager, "upgrade", "-y", "-q", name],
            "remove": [manager, "remove", "-y", "-q", name],
        }
    try:
        run(commands[action], env=env)
    except InstallError:
        if action == "install" and version and manager != "apt-get":
            run([manager, "downgrade", "-y", "-q", spec], env=env)  # pinned to an older version
        else:
            raise


def reconcile_apps(plan: dict[str, Any], mode: str) -> list[dict[str, str]]:
    """Bring applications to the plan's desired state; prune what Patchgate installed and no
    longer wants. Software Patchgate did not install is never removed by pruning."""
    desired: list[dict[str, Any]] = plan.get("apps") or []
    if not desired and not read_state().get("managedApps"):
        return []
    manager = detect_package_manager()
    state = read_state()
    managed: dict[str, dict[str, Any]] = state.get("managedApps", {})
    results: list[dict[str, str]] = []

    def record(name: str, status: str, detail: str) -> None:
        log.info("app %-32s %-13s %s", name, status, detail)
        results.append({"item": f"app:{name}", "status": status, "detail": detail})

    wanted_names = {app["name"] for app in desired}
    for app in desired:
        name, ensure, version = app["name"], app.get("ensure", "present"), app.get("version")
        current = installed_version(manager, name)
        if ensure == "absent":
            action = "remove" if current else None
        elif current is None:
            action = "install"
        elif ensure == "latest":
            action = "upgrade"
        elif version and not version_matches(current, version):
            action = "install"
        else:
            action = None

        if action is None:
            record(name, "compliant", current or "absent")
        elif mode == "audit":
            record(name, "non-compliant", f"would {action} (installed: {current or 'none'})")
        elif action == "upgrade":
            try:
                change_app(manager, "upgrade", name)
                after = installed_version(manager, name)
                record(name, "remediated" if after != current else "compliant", after or "?")
            except InstallError as exc:
                record(name, "failed", str(exc))
        else:
            try:
                change_app(manager, action, name, version if action == "install" else None)
                after = installed_version(manager, name)
                ok = (
                    after is None
                    if action == "remove"
                    else after is not None and (not version or version_matches(after, version))
                )
                record(name, "remediated" if ok else "failed", f"{action}: {current} -> {after}")
            except InstallError as exc:
                record(name, "failed", str(exc))

        if ensure == "absent":
            managed.pop(name, None)
        elif mode != "audit" and (action == "install" or name in managed):
            managed[name] = {"source": app.get("source", ""), "prune": app.get("prune", False)}

    for name, info in sorted(managed.items()):
        if name in wanted_names or not info.get("prune"):
            continue
        if mode == "audit":
            record(name, "non-compliant", f"would prune (from {info.get('source')})")
            continue
        try:
            if installed_version(manager, name):
                change_app(manager, "remove", name)
            record(name, "remediated", f"pruned (was from {info.get('source')})")
            managed.pop(name)
        except InstallError as exc:
            record(name, "failed", f"prune: {exc}")

    if mode != "audit":
        update_state(managedApps=managed)
    return results


def execute(plan: dict[str, Any]) -> dict[str, Any]:
    if plan.get("kind") != "InstallPlan" or plan.get("platform") != "linux":
        raise ValueError("not a linux InstallPlan")
    manager = detect_package_manager()
    results: list[dict[str, str]] = []
    with tempfile.TemporaryDirectory(prefix="patchgate-") as tmp:
        for step in plan["steps"]:
            log.info("== %s (%s)", step["agent"], step["method"])
            install_step(step, manager, Path(tmp))
            validate_step(step)
            results.append({"agent": step["agent"], "status": "ok"})
    apps = reconcile_apps(plan, "enforce")
    failed_apps = [a["item"] for a in apps if a["status"] == "failed"]
    if failed_apps:
        raise InstallError(f"applications could not be reconciled: {', '.join(failed_apps)}")
    controls = apply_hardening(plan.get("hardening"), "enforce")
    failed = [c["control"] for c in controls if c["status"] == "failed"]
    if failed:
        raise InstallError(f"hardening controls could not be remediated: {', '.join(failed)}")
    return {
        "profile": plan["profile"],
        "digest": plan["digest"],
        "steps": results,
        "apps": summarize([{"status": a["status"]} for a in apps]),
        "hardening": summarize(controls),
    }


def summarize(controls: list[dict[str, str]]) -> dict[str, int]:
    summary: dict[str, int] = {}
    for control in controls:
        summary[control["status"]] = summary.get(control["status"], 0) + 1
    return summary


# ---------------------------------------------------------------- drift


def drift_due(interval: str, last_run: float | None, now: float) -> bool:
    if interval == "off":
        return False
    if last_run is None:
        return True
    return now - last_run >= DRIFT_INTERVALS[interval] - DRIFT_SLACK_SECONDS


def run_drift(force: bool = False) -> int:
    """Re-validate agents and hardening from the last applied plan. Runs on a schedule."""
    if not PLAN_FILE.exists():
        log.info("no applied plan yet; nothing to check")
        return 0
    plan = json.loads(PLAN_FILE.read_text())
    drift = plan.get("drift", {})
    interval, mode = drift.get("interval", "30m"), drift.get("mode", "enforce")
    state = read_state()
    if not force and not drift_due(interval, state.get("lastDriftAt"), time.time()):
        log.info("drift check not due (interval %s)", interval)
        return 0

    log.info("== drift check (interval %s, mode %s)", interval, mode)
    findings: list[dict[str, str]] = []
    manager = detect_package_manager()
    with tempfile.TemporaryDirectory(prefix="patchgate-") as tmp:
        for step in plan["steps"]:
            if not step.get("validate") or run_quiet(step["validate"]):
                continue
            if mode == "audit":
                findings.append({"item": f"agent:{step['agent']}", "status": "non-compliant"})
                continue
            try:
                install_step(step, manager, Path(tmp))
                validate_step(step)
                findings.append({"item": f"agent:{step['agent']}", "status": "remediated"})
            except InstallError as exc:
                log.error("%s", exc)
                findings.append({"item": f"agent:{step['agent']}", "status": "failed"})
    for app in reconcile_apps(plan, mode):
        if app["status"] != "compliant":
            findings.append({"item": app["item"], "status": app["status"]})
    for result in apply_hardening(plan.get("hardening"), mode):
        if result["status"] != "compliant":
            findings.append({"item": f"control:{result['control']}", "status": result["status"]})

    state["lastDriftAt"] = time.time()
    write_json(STATE_FILE, state)
    if findings:
        event = {
            "profile": plan["profile"],
            "digest": plan["digest"],
            "mode": mode,
            "findings": findings,
            "detectedAt": now_iso(),
        }
        write_json(DRIFT_EVENT_FILE, event)
        log.warning("PATCHGATE_DRIFT %s", json.dumps(findings))
    else:
        log.info("no drift detected")
    return 1 if any(f["status"] == "failed" for f in findings) else 0


# ---------------------------------------------------------------- entrypoint


def decode_plan(encoded: str) -> bytes:
    """Accept "gz1:" + base64(gzip(json)) (what Patchgate sends) or plain base64 JSON."""
    if encoded.startswith("gz1:"):
        return gzip.decompress(base64.b64decode(encoded[4:], validate=True))
    return base64.b64decode(encoded, validate=True)


def load_plan(args: argparse.Namespace) -> dict[str, Any]:
    raw = decode_plan(args.plan_b64) if args.plan_b64 else args.plan_file.read_bytes()
    plan = json.loads(raw)
    if not isinstance(plan, dict):
        raise ValueError("plan must be a JSON object")
    return plan


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--plan-b64", help="install plan: gz1:<base64 gzip JSON> or base64 JSON")
    source.add_argument("--plan-file", type=Path, help="install plan JSON file")
    source.add_argument("--drift", action="store_true", help="re-check the last applied plan")
    parser.add_argument("--force", action="store_true", help="ignore digest/interval and run now")
    args = parser.parse_args(argv)

    LOG_DIR.mkdir(parents=True, exist_ok=True)
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(message)s",
        handlers=[logging.StreamHandler(sys.stdout), logging.FileHandler(LOG_DIR / "install.log")],
    )
    if args.drift:
        return run_drift(force=args.force)
    try:
        plan = load_plan(args)
    except (ValueError, OSError) as exc:
        log.error("invalid plan: %s", exc)
        return 2

    if not args.force:
        state = read_state()
        if state.get("digest") == plan.get("digest") and state.get("status") == "success":
            log.info("plan %s already applied; validating only", plan.get("digest"))
            try:
                for step in plan["steps"]:
                    validate_step(step)
                return 0
            except InstallError:
                log.warning("validation failed; re-applying plan")

    try:
        result = execute(plan)
    except (InstallError, ValueError) as exc:
        log.error("FAILED: %s", exc)
        update_state(digest=plan.get("digest"), status="failed", error=str(exc))
        return 1
    write_json(PLAN_FILE, plan)
    update_state(digest=plan["digest"], status="success", result=result, error=None)
    log.info("SUCCESS: profile %s applied", plan["profile"])
    print(json.dumps({"patchgate": result}))
    return 0


def now_iso() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def write_json(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, indent=2))
    tmp.replace(path)


def read_state() -> dict[str, Any]:
    if not STATE_FILE.exists():
        return {}
    state: dict[str, Any] = json.loads(STATE_FILE.read_text())
    return state


def update_state(**fields: Any) -> None:
    state = read_state()
    state.update({k: v for k, v in fields.items() if v is not None})
    for key in [k for k, v in fields.items() if v is None]:
        state.pop(key, None)
    state["updatedAt"] = now_iso()
    write_json(STATE_FILE, state)


if __name__ == "__main__":
    sys.exit(main())

PATCHGATE_EOF

$installer = @'
#Requires -Version 5.1
<#
.SYNOPSIS
    Patchgate install-plan executor for Windows.

.DESCRIPTION
    Runs inside the VM as SYSTEM/Administrator. Applies an install plan produced by
    `python -m patchgate compile`: agents (choco, msi, exe, script), Chocolatey packages and
    their validation commands. It never calls a cloud API.

    Idempotent: steps whose validation already passes are skipped, and a plan whose digest
    was already applied successfully is only re-validated.

    -Drift re-checks the last applied plan (agents and hardening controls) when its interval is
    due, correcting or reporting drift and leaving drift-event.json for the provider to publish.

    Exit codes: 0 success, 1 failure, 2 invalid input, 3010 reboot required (re-run after reboot).
#>
[CmdletBinding(DefaultParameterSetName = 'Base64')]
param(
    [Parameter(Mandatory, ParameterSetName = 'Base64')]
    [string]$PlanBase64,

    [Parameter(Mandatory, ParameterSetName = 'File')]
    [string]$PlanFile,

    [Parameter(Mandatory, ParameterSetName = 'Drift')]
    [switch]$Drift,

    [switch]$Force
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$Root = Join-Path $env:ProgramData 'Patchgate'
$LogFile = Join-Path $Root 'logs\install.log'
$StateFile = Join-Path $Root 'state.json'
$AppliedPlanFile = Join-Path $Root 'plan.json'          # last applied plan, re-used by drift runs
$ComplianceFile = Join-Path $Root 'compliance.json'     # evidence: last result of every control
$DriftEventFile = Join-Path $Root 'drift-event.json'    # picked up and published by the provider
$DriftIntervals = @{ '30m' = 1800; '1h' = 3600; '2h' = 7200; '6h' = 21600; '12h' = 43200; '24h' = 86400 }
$DriftSlackSeconds = 120
$script:HardeningRebootRequired = $false
$script:AppsRebootRequired = $false

# Chocolatey is bootstrapped from its pinned package, never from a remote install script.
$ChocoVersion = '2.7.5'
$ChocoSha256 = 'f86f99a18d236c2f99e6f67a20be7adc65c6c7756bf6cf3b43759e7ec0aa5839'
$ChocoUrl = "https://packages.chocolatey.org/chocolatey.$ChocoVersion.nupkg"

# Child scripts run with the same PowerShell executable as this installer (5.1 or 7).
$PowerShellExe = (Get-Process -Id $PID).Path
$RebootExitCode = 3010
$SuccessCodes = @(0, 1641, 3010)
$ValidateAttempts = 5
$ValidateDelaySeconds = 6

function Write-PatchgateLog {
    # Write-Host on purpose: Write-Output would leak log lines into function return values.
    # SSM Run Command captures the host stream as command output.
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSAvoidUsingWriteHost', '', Justification = 'Logs must not pollute the pipeline')]
    param([string]$Message, [string]$Level = 'INFO')
    $line = '{0} {1} {2}' -f (Get-Date -Format 'yyyy-MM-ddTHH:mm:ssK'), $Level, $Message
    Write-Host $line
    # Share read/write: log shippers (e.g. the CloudWatch agent) keep this file open.
    # A logging failure must never abort an installation.
    try {
        $stream = [IO.File]::Open($LogFile, [IO.FileMode]::Append, [IO.FileAccess]::Write,
            ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
        try {
            $writer = New-Object IO.StreamWriter($stream, (New-Object Text.UTF8Encoding $false))
            $writer.WriteLine($line)
            $writer.Flush()
        }
        finally {
            $stream.Dispose()
        }
    }
    catch {
        Write-Host "WARN could not write $LogFile ($($_.Exception.Message))"
    }
}

function Write-JsonFile {
    # UTF-8 without BOM: consumers such as the AWS CLI and JSON parsers reject a BOM.
    param([string]$Path, $Data)
    $json = $Data | ConvertTo-Json -Depth 8
    $tmp = "$Path.tmp"
    [IO.File]::WriteAllText($tmp, $json, (New-Object Text.UTF8Encoding $false))
    Move-Item -Path $tmp -Destination $Path -Force
}

function Get-Prop {
    # StrictMode-safe property access with a default (older plans may lack newer fields).
    param($Object, [string]$Name, $Default = $null)
    if ($null -ne $Object -and $Object.PSObject.Properties.Name -contains $Name) { return $Object.$Name }
    return $Default
}

function Read-State {
    $state = @{}
    if (Test-Path $StateFile) {
        $raw = Get-Content -Raw -Path $StateFile | ConvertFrom-Json
        foreach ($p in $raw.PSObject.Properties) { $state[$p.Name] = $p.Value }
    }
    return $state
}

function Save-State {
    # Merge into the existing state so fields such as lastDriftAt survive.
    param([hashtable]$Fields)
    $state = Read-State
    foreach ($key in $Fields.Keys) {
        if ($null -eq $Fields[$key]) { $state.Remove($key) } else { $state[$key] = $Fields[$key] }
    }
    $state['updatedAt'] = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
    Write-JsonFile -Path $StateFile -Data $state
}

function Invoke-Native {
    # Windows PowerShell 5.1 turns native stderr into terminating errors under 'Stop'.
    param([string]$FilePath, [string[]]$Arguments)
    $previous = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $output = & $FilePath @Arguments 2>&1
        $code = $LASTEXITCODE
    }
    finally {
        $ErrorActionPreference = $previous
    }
    foreach ($line in $output) { Write-PatchgateLog "  $line" }
    return $code
}

function Invoke-PlanScript {
    # Runs catalog script content in a child process. Returns its exit code.
    param([string]$Script)
    $path = Join-Path $env:TEMP ("patchgate-{0}.ps1" -f [guid]::NewGuid())
    Set-Content -Path $path -Value $Script -Encoding UTF8
    try {
        return Invoke-Native -FilePath $PowerShellExe -Arguments @(
            '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', $path)
    }
    finally {
        Remove-Item -Path $path -Force -ErrorAction SilentlyContinue
    }
}

function Get-VerifiedDownload {
    param([string]$Url, [string]$Sha256, [string]$Destination)
    if (-not $Url.StartsWith('https://')) { throw "refusing non-https source: $Url" }
    Write-PatchgateLog "downloading $Url"
    Invoke-WebRequest -Uri $Url -OutFile $Destination -UseBasicParsing
    $actual = (Get-FileHash -Algorithm SHA256 -Path $Destination).Hash.ToLowerInvariant()
    if ($actual -ne $Sha256.ToLowerInvariant()) {
        Remove-Item -Path $Destination -Force
        throw "checksum mismatch for ${Url}: expected $Sha256, got $actual"
    }
    Write-PatchgateLog "checksum OK ($actual)"
    return $Destination
}

function Get-Chocolatey {
    # PATCHGATE_CHOCO_EXE lets tests point at a fake Chocolatey; it is never set in production.
    if ($env:PATCHGATE_CHOCO_EXE) { return $env:PATCHGATE_CHOCO_EXE }
    $choco = Join-Path $env:ProgramData 'chocolatey\bin\choco.exe'
    if (Test-Path $choco) { return $choco }
    Write-PatchgateLog "installing Chocolatey $ChocoVersion from pinned package"
    $work = Join-Path $env:TEMP 'patchgate-chocolatey'
    New-Item -ItemType Directory -Force -Path $work | Out-Null
    $package = Get-VerifiedDownload -Url $ChocoUrl -Sha256 $ChocoSha256 -Destination (Join-Path $work 'chocolatey.zip')
    Expand-Archive -Path $package -DestinationPath (Join-Path $work 'pkg') -Force
    & (Join-Path $work 'pkg\tools\chocolateyInstall.ps1') | Out-Null
    if (-not (Test-Path $choco)) { throw 'Chocolatey installation failed' }
    [void](Invoke-Native -FilePath $choco -Arguments @('feature', 'enable', '-n', 'allowGlobalConfirmation'))
    return $choco
}

function Get-ChocoVersion {
    # Installed version of a Chocolatey package, or $null.
    param([string]$Name)
    $choco = Get-Chocolatey
    $previous = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try { $output = & $choco list $Name --exact --limit-output 2>$null }
    finally { $ErrorActionPreference = $previous }
    foreach ($line in @($output)) {
        $parts = "$line".Split('|')
        if ($parts.Count -ge 2 -and $parts[0] -ieq $Name) { return $parts[1].Trim() }
    }
    return $null
}

function Invoke-ChocoChange {
    # install (optionally pinned, allowing downgrades) | upgrade | remove. Returns the exit code.
    param([string]$Action, [string]$Name, [string]$Version)
    $choco = Get-Chocolatey
    switch ($Action) {
        'install' {
            $arguments = @('upgrade', $Name, '-y', '--no-progress', '--limit-output')
            if ($Version) { $arguments += @('--version', $Version, '--allow-downgrade') }
        }
        'upgrade' { $arguments = @('upgrade', $Name, '-y', '--no-progress', '--limit-output') }
        'remove' { $arguments = @('uninstall', $Name, '-y', '--no-progress', '--limit-output') }
        default { throw "unknown app action $Action" }
    }
    $code = Invoke-Native -FilePath $choco -Arguments $arguments
    if ($SuccessCodes -notcontains $code) { throw "choco $Action $Name failed (exit $code)" }
    return $code
}

function Get-DesiredApp {
    # Plan apps, plus the legacy 'chocolatey' list from older plans (present, profile, no prune).
    param($Plan)
    $apps = @(Get-Prop $Plan 'apps' @())
    foreach ($legacy in @(Get-Prop $Plan 'chocolatey' @())) {
        if ($legacy) {
            $apps += [pscustomobject]@{ name = $legacy.name; version = (Get-Prop $legacy 'version'); ensure = 'present'; source = 'profile'; prune = $false }
        }
    }
    return $apps | Where-Object { $_ }
}

function Invoke-AppReconcile {
    # Bring applications to the plan's desired state and prune what Patchgate installed and no
    # longer wants. Software Patchgate did not install is never removed by pruning.
    param($Plan, [string]$Mode)
    $desired = @(Get-DesiredApp $Plan)
    $state = Read-State
    $managed = @{}
    if ($state.ContainsKey('managedApps') -and $state['managedApps']) {
        foreach ($p in $state['managedApps'].PSObject.Properties) { $managed[$p.Name] = $p.Value }
    }
    $results = @()
    if ($desired.Count -eq 0 -and $managed.Count -eq 0) { return $results }

    $wanted = @{}
    foreach ($app in $desired) {
        $name = $app.name
        $wanted[$name] = $true
        $ensure = Get-Prop $app 'ensure' 'present'
        $version = Get-Prop $app 'version'
        $current = Get-ChocoVersion $name
        $action = $null
        if ($ensure -eq 'absent') { if ($current) { $action = 'remove' } }
        elseif (-not $current) { $action = 'install' }
        elseif ($ensure -eq 'latest') { $action = 'upgrade' }
        elseif ($version -and $current -ne $version) { $action = 'install' }

        if (-not $action) { $status = 'compliant'; $detail = if ($current) { $current } else { 'absent' } }
        elseif ($Mode -eq 'audit') { $status = 'non-compliant'; $detail = "would $action (installed: $current)" }
        else {
            try {
                if ((Invoke-ChocoChange -Action $action -Name $name -Version $version) -eq $RebootExitCode) {
                    $script:AppsRebootRequired = $true
                }
                $after = Get-ChocoVersion $name
                if ($action -eq 'remove') { $ok = -not $after }
                elseif ($action -eq 'upgrade') { $ok = [bool]$after }
                else { $ok = $after -and (-not $version -or $after -eq $version) }
                $status = if (-not $ok) { 'failed' } elseif ($action -eq 'upgrade' -and $after -eq $current) { 'compliant' } else { 'remediated' }
                $detail = "${action}: $current -> $after"
            }
            catch { $status = 'failed'; $detail = "$_" }
        }
        Write-PatchgateLog ("app {0,-32} {1,-13} {2}" -f $name, $status, $detail)
        $results += [ordered]@{ item = "app:$name"; status = $status; detail = $detail }

        if ($ensure -eq 'absent') { $managed.Remove($name) }
        elseif ($Mode -ne 'audit' -and ($action -eq 'install' -or $managed.ContainsKey($name))) {
            $managed[$name] = [ordered]@{ source = (Get-Prop $app 'source' ''); prune = [bool](Get-Prop $app 'prune' $false) }
        }
    }

    foreach ($name in @($managed.Keys | Sort-Object)) {
        $info = $managed[$name]
        $prune = [bool](Get-Prop ([pscustomobject]$info) 'prune' $false)
        if ($wanted.ContainsKey($name) -or -not $prune) { continue }
        $source = Get-Prop ([pscustomobject]$info) 'source' ''
        if ($Mode -eq 'audit') {
            $results += [ordered]@{ item = "app:$name"; status = 'non-compliant'; detail = "would prune (from $source)" }
            continue
        }
        try {
            if (Get-ChocoVersion $name) { [void](Invoke-ChocoChange -Action 'remove' -Name $name) }
            $results += [ordered]@{ item = "app:$name"; status = 'remediated'; detail = "pruned (was from $source)" }
            Write-PatchgateLog ("app {0,-32} {1,-13} pruned (was from {2})" -f $name, 'remediated', $source)
            $managed.Remove($name)
        }
        catch {
            $results += [ordered]@{ item = "app:$name"; status = 'failed'; detail = "prune: $_" }
        }
    }
    if ($Mode -ne 'audit') { Save-State @{ managedApps = $managed } }
    return $results
}

function Test-Step {
    param($Step)
    if (-not ($Step.PSObject.Properties.Name -contains 'validate')) { return $false }
    return (Invoke-PlanScript -Script $Step.validate) -eq 0
}

function Assert-Step {
    param($Step)
    if (-not ($Step.PSObject.Properties.Name -contains 'validate')) { return }
    for ($attempt = 1; $attempt -le $ValidateAttempts; $attempt++) {
        if ((Invoke-PlanScript -Script $Step.validate) -eq 0) {
            Write-PatchgateLog "validate OK: $($Step.agent)"
            return
        }
        Write-PatchgateLog "validate attempt $attempt/$ValidateAttempts failed for $($Step.agent)"
        Start-Sleep -Seconds $ValidateDelaySeconds
    }
    throw "validation failed for $($Step.agent)"
}

function Install-Step {
    # Returns $true when the step requested a reboot.
    param($Step, [string]$WorkDir)
    $props = $Step.PSObject.Properties.Name
    $code = 0
    switch ($Step.method) {
        'choco' {
            $version = if ($props -contains 'version') { $Step.version } else { $null }
            $code = Invoke-ChocoChange -Action install -Name $Step.package -Version $version
        }
        { $_ -in 'msi', 'exe' } {
            $file = Get-VerifiedDownload -Url $Step.source -Sha256 $Step.sha256 `
                -Destination (Join-Path $WorkDir ("{0}.{1}" -f $Step.agent, $Step.method))
            $extra = if ($props -contains 'args') { $Step.args } else { '' }
            if ($Step.method -eq 'msi') {
                $process = Start-Process -FilePath 'msiexec.exe' -Wait -PassThru `
                    -ArgumentList ('/i "{0}" /qn /norestart {1}' -f $file, $extra)
            }
            else {
                $process = Start-Process -FilePath $file -ArgumentList $extra -Wait -PassThru
            }
            $code = $process.ExitCode
            if ($SuccessCodes -notcontains $code) { throw "$($Step.agent) installer exited with $code" }
        }
        'script' {
            $code = Invoke-PlanScript -Script $Step.script
            if ($code -ne 0 -and $code -ne $RebootExitCode) { throw "$($Step.agent) script exited with $code" }
        }
        default { throw "unsupported method on windows: $($Step.method)" }
    }
    if ($code -eq $RebootExitCode) { return $true }
    if ($props -contains 'postInstall') {
        $post = Invoke-PlanScript -Script $Step.postInstall
        if ($post -eq $RebootExitCode) { return $true }
        if ($post -ne 0) { throw "$($Step.agent) postInstall exited with $post" }
    }
    return $false
}

function Invoke-Hardening {
    # Run the profile's hardening engine and record evidence. Returns one result per control:
    # compliant | remediated | non-compliant (audit) | failed (remediation did not fix it).
    param($Hardening, [string]$Mode)
    $results = @()
    if ($null -eq $Hardening -or $Hardening -is [string]) { return $results }
    switch ($Hardening.engine) {
        'controls' { $results = @(Invoke-ControlsEngine -Hardening $Hardening -Mode $Mode) }
        'dsc' { $results = @(Invoke-DscEngine -Hardening $Hardening -Mode $Mode) }
        default { throw "unsupported hardening engine: $($Hardening.engine)" }
    }
    Write-JsonFile -Path $ComplianceFile -Data ([ordered]@{
            engine    = $Hardening.engine
            level     = (Get-Prop $Hardening 'level' (Get-Prop $Hardening 'baseline' ''))
            mode      = $Mode
            checkedAt = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
            controls  = $results
        })
    return $results
}

function Invoke-ControlsEngine {
    param($Hardening, [string]$Mode)
    $results = @()
    foreach ($control in $Hardening.controls) {
        if ((Invoke-PlanScript -Script $control.check) -eq 0) {
            $status = 'compliant'
        }
        elseif ($Mode -eq 'audit') {
            $status = 'non-compliant'
        }
        else {
            $code = Invoke-PlanScript -Script $control.remediate
            if ($code -ne 0) { Write-PatchgateLog "control $($control.name) remediation exited with $code" 'ERROR' }
            $status = if ((Invoke-PlanScript -Script $control.check) -eq 0) { 'remediated' } else { 'failed' }
        }
        Write-PatchgateLog ("control {0,-32} {1}" -f $control.name, $status)
        $results += [ordered]@{ control = $control.name; cis = (Get-Prop $control 'cis' ''); status = $status }
    }
    return $results
}

function Invoke-DscEngine {
    # Pinned DSC modules + baseline configuration applied by the LCM (see PatchgateDsc.psm1).
    param($Hardening, [string]$Mode)
    Import-Module (Join-Path $PSScriptRoot 'PatchgateDsc.psm1') -Force
    $modulesRoot = Join-Path $env:ProgramFiles 'WindowsPowerShell\Modules'
    $work = Join-Path $env:TEMP ("patchgate-dsc-{0}" -f [guid]::NewGuid())
    New-Item -ItemType Directory -Force -Path $work | Out-Null
    try {
        foreach ($module in $Hardening.modules) {
            $package = Get-VerifiedDownload -Url $module.source -Sha256 $module.sha256 `
                -Destination (Join-Path $work "$($module.name).nupkg")
            [void](Install-PatchgateModule -Name $module.name -Version $module.version -Package $package -ModulesRoot $modulesRoot)
        }
        Write-PatchgateLog "applying DSC baseline $($Hardening.baseline) (mode $Mode)"
        $outcome = Invoke-PatchgateDscBaseline -Baseline $Hardening -Mode $Mode -WorkDir $work
    }
    finally {
        Remove-Item -Path $work -Recurse -Force -ErrorAction SilentlyContinue
    }
    if ($outcome.rebootRequired) {
        Write-PatchgateLog 'DSC baseline requires a reboot to complete' 'WARN'
        $script:HardeningRebootRequired = $true
    }
    $results = @($outcome.results)
    $summary = ((Get-Summary $results).GetEnumerator() | Sort-Object Key | ForEach-Object { "$($_.Key)=$($_.Value)" }) -join ' '
    Write-PatchgateLog "dsc baseline $($Hardening.baseline): $summary ($($results.Count) rules)"
    foreach ($r in $results) {
        if ($r.status -in 'failed', 'non-compliant') { Write-PatchgateLog ("rule {0,-10} {1,-13} {2}" -f $r.cis, $r.status, $r.title) }
    }
    return $results
}

function Get-Summary {
    param($Results)
    $summary = @{}
    foreach ($r in $Results) {
        if ($summary.ContainsKey($r.status)) { $summary[$r.status] += 1 } else { $summary[$r.status] = 1 }
    }
    return $summary
}

function Invoke-Drift {
    # Returns the exit code for a drift run.
    if (-not (Test-Path $AppliedPlanFile)) {
        Write-PatchgateLog 'no applied plan yet; nothing to check'
        return 0
    }
    $plan = Get-Content -Raw -Path $AppliedPlanFile | ConvertFrom-Json
    $driftCfg = Get-Prop $plan 'drift'
    $interval = Get-Prop $driftCfg 'interval' '30m'
    $mode = Get-Prop $driftCfg 'mode' 'enforce'
    $state = Read-State
    $now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    if ($interval -eq 'off') { Write-PatchgateLog 'drift checks are off for this profile'; return 0 }
    if (-not $Force -and $state.ContainsKey('lastDriftAt') -and
        ($now - [double]$state['lastDriftAt']) -lt ($DriftIntervals[$interval] - $DriftSlackSeconds)) {
        Write-PatchgateLog "drift check not due (interval $interval)"
        return 0
    }

    Write-PatchgateLog "== drift check (interval $interval, mode $mode)"
    $findings = @()
    $work = Join-Path $env:TEMP ("patchgate-{0}" -f [guid]::NewGuid())
    New-Item -ItemType Directory -Force -Path $work | Out-Null
    try {
        foreach ($step in $plan.steps) {
            if (-not ($step.PSObject.Properties.Name -contains 'validate') -or (Test-Step -Step $step)) { continue }
            if ($mode -eq 'audit') { $findings += [ordered]@{ item = "agent:$($step.agent)"; status = 'non-compliant' }; continue }
            try {
                [void](Install-Step -Step $step -WorkDir $work)
                Assert-Step -Step $step
                $findings += [ordered]@{ item = "agent:$($step.agent)"; status = 'remediated' }
            }
            catch {
                Write-PatchgateLog "agent $($step.agent) could not be restored: $_" 'ERROR'
                $findings += [ordered]@{ item = "agent:$($step.agent)"; status = 'failed' }
            }
        }
    }
    finally {
        Remove-Item -Path $work -Recurse -Force -ErrorAction SilentlyContinue
    }
    foreach ($a in @(Invoke-AppReconcile -Plan $plan -Mode $mode)) {
        if ($a.status -ne 'compliant') { $findings += [ordered]@{ item = $a.item; status = $a.status } }
    }
    foreach ($r in @(Invoke-Hardening -Hardening (Get-Prop $plan 'hardening') -Mode $mode)) {
        if ($r.status -ne 'compliant') { $findings += [ordered]@{ item = "control:$($r.control)"; status = $r.status } }
    }

    Save-State @{ lastDriftAt = $now }
    if ($findings.Count -gt 0) {
        Write-JsonFile -Path $DriftEventFile -Data ([ordered]@{
                profile    = $plan.profile
                digest     = $plan.digest
                mode       = $mode
                findings   = $findings
                detectedAt = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
            })
        Write-PatchgateLog ("PATCHGATE_DRIFT " + ($findings | ConvertTo-Json -Compress -Depth 4)) 'WARN'
    }
    else {
        Write-PatchgateLog 'no drift detected'
    }
    if ($findings | Where-Object { $_.status -eq 'failed' }) { return 1 }
    return 0
}

# ------------------------------------------------------------------ main
New-Item -ItemType Directory -Force -Path (Split-Path $LogFile) | Out-Null

if ($Drift -and $PSCmdlet.ParameterSetName -eq 'Drift') {
    try { exit (Invoke-Drift) }
    catch { Write-PatchgateLog "drift check FAILED: $_" 'ERROR'; exit 1 }
}

try {
    $json = if ($PSCmdlet.ParameterSetName -eq 'Base64') {
        # "gz1:" + base64(gzip(json)) is what Patchgate sends; plain base64 JSON is also accepted.
        if ($PlanBase64.StartsWith('gz1:')) {
            $bytes = [Convert]::FromBase64String($PlanBase64.Substring(4))
            $gzip = New-Object IO.Compression.GZipStream((New-Object IO.MemoryStream(, $bytes)), [IO.Compression.CompressionMode]::Decompress)
            $reader = New-Object IO.StreamReader($gzip, [Text.Encoding]::UTF8)
            try { $reader.ReadToEnd() } finally { $reader.Dispose() }
        }
        else {
            [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($PlanBase64))
        }
    }
    else {
        Get-Content -Raw -Path $PlanFile
    }
    $plan = $json | ConvertFrom-Json
    if ($plan.kind -ne 'InstallPlan' -or $plan.platform -ne 'windows') { throw 'not a windows InstallPlan' }
}
catch {
    Write-PatchgateLog "invalid plan: $_" 'ERROR'
    exit 2
}

if (-not $Force) {
    $state = Read-State
    if ($state['digest'] -eq $plan.digest -and $state['status'] -eq 'success') {
        Write-PatchgateLog "plan $($plan.digest) already applied; validating only"
        try {
            foreach ($step in $plan.steps) { Assert-Step -Step $step }
            exit 0
        }
        catch {
            Write-PatchgateLog "validation failed ($_); re-applying plan" 'WARN'
        }
    }
}

$work = Join-Path $env:TEMP ("patchgate-{0}" -f [guid]::NewGuid())
New-Item -ItemType Directory -Force -Path $work | Out-Null
$results = @()
try {
    foreach ($step in $plan.steps) {
        Write-PatchgateLog "== $($step.agent) ($($step.method))"
        if (Test-Step -Step $step) {
            Write-PatchgateLog "already installed and valid; skipping"
            $results += @{ agent = $step.agent; status = 'skipped' }
            continue
        }
        if (Install-Step -Step $step -WorkDir $work) {
            Write-PatchgateLog "$($step.agent) requested a reboot; re-run after restart" 'WARN'
            Save-State @{ digest = $plan.digest; status = 'reboot-pending'; agent = $step.agent }
            exit $RebootExitCode
        }
        Assert-Step -Step $step
        $results += @{ agent = $step.agent; status = 'ok' }
    }

    $appResults = @(Invoke-AppReconcile -Plan $plan -Mode 'enforce')
    $failedApps = @($appResults | Where-Object { $_.status -eq 'failed' } | ForEach-Object { $_.item })
    if ($failedApps.Count -gt 0) { throw "applications could not be reconciled: $($failedApps -join ', ')" }

    $controls = @(Invoke-Hardening -Hardening (Get-Prop $plan 'hardening') -Mode 'enforce')
    $failed = @($controls | Where-Object { $_.status -eq 'failed' } | ForEach-Object { $_.control })
    if ($failed.Count -gt 0) { throw "hardening controls could not be remediated: $($failed -join ', ')" }
}
catch {
    Write-PatchgateLog "FAILED: $_" 'ERROR'
    Save-State @{ digest = $plan.digest; status = 'failed'; error = "$_" }
    exit 1
}
finally {
    Remove-Item -Path $work -Recurse -Force -ErrorAction SilentlyContinue
}

$hardeningSummary = Get-Summary $controls
Write-JsonFile -Path $AppliedPlanFile -Data $plan
Save-State @{
    digest = $plan.digest; status = 'success'; error = $null
    result = @{ profile = $plan.profile; steps = $results; hardening = $hardeningSummary }
}
Write-PatchgateLog "SUCCESS: profile $($plan.profile) applied"
Write-Output (@{ patchgate = @{ profile = $plan.profile; digest = $plan.digest; steps = $results; hardening = $hardeningSummary } } | ConvertTo-Json -Depth 5 -Compress)
if ($script:AppsRebootRequired -or $script:HardeningRebootRequired) { exit $RebootExitCode }
exit 0

'@

$dscModule = @'
#Requires -Version 5.1
<#
.SYNOPSIS
    "dsc" hardening engine for Patchgate (ADR 0007).

.DESCRIPTION
    Installs pinned DSC modules, compiles the baseline's configuration, applies it with the Local
    Configuration Manager (ApplyOnly: Patchgate drives drift) and reports one result per CIS rule.
    DSC cmdlets are resolved at run time, so tests can replace them with stubs.
#>

Set-StrictMode -Version Latest

$script:CisId = '\](?<id>\d+(?:\.\d+)+)\s+-\s'

function Expand-PatchgateZip {
    # Extract a zip (e.g. a .nupkg), refusing entries that would land outside Destination.
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$Destination)
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    New-Item -ItemType Directory -Force -Path $Destination | Out-Null
    $root = [IO.Path]::GetFullPath($Destination).TrimEnd('\', '/') + [IO.Path]::DirectorySeparatorChar
    $zip = [IO.Compression.ZipFile]::OpenRead($Path)
    try {
        foreach ($entry in $zip.Entries) {
            $target = [IO.Path]::GetFullPath((Join-Path $Destination $entry.FullName))
            if (-not $target.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) {
                throw "unsafe path in archive: $($entry.FullName)"
            }
        }
        foreach ($entry in $zip.Entries) {
            $target = [IO.Path]::GetFullPath((Join-Path $Destination $entry.FullName))
            if ($entry.FullName.EndsWith('/') -or $entry.FullName.EndsWith('\')) {
                New-Item -ItemType Directory -Force -Path $target | Out-Null
                continue
            }
            New-Item -ItemType Directory -Force -Path (Split-Path $target) | Out-Null
            [IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $target, $true)
        }
    }
    finally {
        $zip.Dispose()
    }
}

function Install-PatchgateModule {
    # Install a verified .nupkg as ModulesRoot\<Name>\<Version>; NuGet metadata is removed.
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][string]$Version,
        [Parameter(Mandatory)][string]$Package,
        [Parameter(Mandatory)][string]$ModulesRoot
    )
    $target = Join-Path (Join-Path $ModulesRoot $Name) $Version
    $marker = Join-Path $target '.patchgate'
    if (Test-Path $marker) { return $target }
    if (Test-Path $target) { Remove-Item -Recurse -Force -Path $target }
    Expand-PatchgateZip -Path $Package -Destination $target
    foreach ($meta in @('_rels', 'package', '[Content_Types].xml')) {
        Remove-Item -LiteralPath (Join-Path $target $meta) -Recurse -Force -ErrorAction SilentlyContinue
    }
    Get-ChildItem -Path $target -Filter '*.nuspec' | Remove-Item -Force
    Set-Content -Path $marker -Value $Version
    return $target
}

function ConvertTo-PowerShellLiteral {
    param($Value)
    if ($Value -is [bool]) { if ($Value) { return '$true' } else { return '$false' } }
    if ($Value -is [int] -or $Value -is [long] -or $Value -is [double]) { return [string]$Value }
    return "'" + ([string]$Value).Replace("'", "''") + "'"
}

function Get-PatchgateDscScript {
    # PowerShell source of the configuration for a baseline; compiled into a MOF in a child process.
    param([Parameter(Mandatory)]$Baseline, [Parameter(Mandatory)][string]$OutputPath)
    $resource = $Baseline.resource
    $lines = @(
        'Configuration PatchgateBaseline {'
        "    Import-DscResource -ModuleName $(ConvertTo-PowerShellLiteral $resource.module) -Name $(ConvertTo-PowerShellLiteral $resource.name)"
        "    Node 'localhost' {"
        "        $($resource.name) 'Patchgate' {"
    )
    $exclude = @()
    if ($Baseline.PSObject.Properties.Name -contains 'exclude') { $exclude = @($Baseline.exclude) }
    $lines += '            ExcludeList = @(' + (($exclude | ForEach-Object { ConvertTo-PowerShellLiteral $_ }) -join ', ') + ')'
    if ($Baseline.PSObject.Properties.Name -contains 'parameters' -and $null -ne $Baseline.parameters) {
        foreach ($p in $Baseline.parameters.PSObject.Properties) {
            if ($p.Name -notmatch '^[A-Za-z][A-Za-z0-9]*$') { throw "invalid DSC parameter name: $($p.Name)" }
            $lines += "            $($p.Name) = $(ConvertTo-PowerShellLiteral $p.Value)"
        }
    }
    $lines += @(
        '        }'
        '    }'
        '}'
        "PatchgateBaseline -OutputPath $(ConvertTo-PowerShellLiteral $OutputPath) | Out-Null"
    )
    return ($lines -join [Environment]::NewLine)
}

function Get-CisId {
    param([string]$ResourceId)
    if ($ResourceId -match $script:CisId) { return $Matches['id'] }
    return $null
}

function ConvertTo-PatchgateDscEvidence {
    # Before/after Test-DscConfiguration results -> one result per CIS rule (worst status wins).
    param([Parameter(Mandatory)]$Before, $After, [Parameter(Mandatory)][string]$Mode)
    $rank = @{ 'compliant' = 0; 'remediated' = 1; 'non-compliant' = 2; 'failed' = 3 }
    $okBefore = @{}
    foreach ($r in @($Before.ResourcesInDesiredState)) { if ($r) { $okBefore[$r.ResourceId] = $true } }
    $okAfter = @{}
    if ($After) { foreach ($r in @($After.ResourcesInDesiredState)) { if ($r) { $okAfter[$r.ResourceId] = $true } } }

    $rules = @{}
    $all = @($Before.ResourcesInDesiredState) + @($Before.ResourcesNotInDesiredState) | Where-Object { $_ }
    foreach ($resource in $all) {
        $id = Get-CisId $resource.ResourceId
        if (-not $id) { continue }
        if ($okBefore.ContainsKey($resource.ResourceId)) { $status = 'compliant' }
        elseif ($Mode -eq 'audit') { $status = 'non-compliant' }
        elseif ($okAfter.ContainsKey($resource.ResourceId)) { $status = 'remediated' }
        else { $status = 'failed' }
        if (-not $rules.ContainsKey($id) -or $rank[$status] -gt $rank[$rules[$id].status]) {
            $title = ($resource.ResourceId -replace '^\[[^\]]+\]', '' -replace '::\[.*$', '')
            $rules[$id] = [ordered]@{ control = "cis-$id"; cis = $id; status = $status; title = $title.Substring(0, [Math]::Min(160, $title.Length)) }
        }
    }
    $ordered = $rules.Keys | Sort-Object { [version](($_ + '.0.0.0').Split('.')[0..3] -join '.') }, { $_ }
    return @($ordered | ForEach-Object { $rules[$_] })
}

function Initialize-PatchgateLcm {
    # Patchgate drives drift itself: the LCM only applies when asked and never reboots on its own.
    param([Parameter(Mandatory)][string]$WorkDir)
    $meta = Join-Path $WorkDir 'meta'
    $script = @"
[DSCLocalConfigurationManager()]
Configuration PatchgateLcm {
    Node 'localhost' {
        Settings {
            ConfigurationMode  = 'ApplyOnly'
            RefreshMode        = 'Push'
            RebootNodeIfNeeded = `$false
        }
    }
}
PatchgateLcm -OutputPath '$($meta.Replace("'", "''"))' | Out-Null
"@
    $file = Join-Path $WorkDir 'lcm.ps1'
    Set-Content -Path $file -Value $script -Encoding UTF8
    & powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $file
    if ($LASTEXITCODE -ne 0) { throw "LCM meta-configuration failed ($LASTEXITCODE)" }
    Set-DscLocalConfigurationManager -Path $meta -Force
}

function Initialize-PatchgateWinRm {
    # Large baselines (hundreds of resources) exceed WinRM's default 500 KB envelope, which DSC
    # cmdlets use locally. Raise it once; only the local WS-Management limit changes.
    param([int]$EnvelopeKb = 8192)
    $current = [int](Get-Item -Path 'WSMan:\localhost\MaxEnvelopeSizekb').Value
    if ($current -lt $EnvelopeKb) { Set-Item -Path 'WSMan:\localhost\MaxEnvelopeSizekb' -Value $EnvelopeKb }
}

function Invoke-PatchgateDscBaseline {
    <#
        Apply (enforce) or only evaluate (audit) a DSC baseline. Returns @{ results; rebootRequired }.
        -Prepare, -Compiler and -LcmInitializer wrap Windows-only steps so tests can replace them.
    #>
    param(
        [Parameter(Mandatory)]$Baseline,
        [Parameter(Mandatory)][string]$Mode,
        [Parameter(Mandatory)][string]$WorkDir,
        [scriptblock]$Compiler = {
            param([string]$ScriptPath)
            & powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $ScriptPath
            if ($LASTEXITCODE -ne 0) { throw "DSC compilation failed ($LASTEXITCODE)" }
        },
        [scriptblock]$LcmInitializer = { param([string]$Dir) Initialize-PatchgateLcm -WorkDir $Dir },
        [scriptblock]$Prepare = { Initialize-PatchgateWinRm }
    )
    & $Prepare
    $mofDir = Join-Path $WorkDir 'mof'
    $scriptPath = Join-Path $WorkDir 'baseline.ps1'
    Set-Content -Path $scriptPath -Value (Get-PatchgateDscScript -Baseline $Baseline -OutputPath $mofDir) -Encoding UTF8
    & $Compiler $scriptPath
    $mof = Join-Path $mofDir 'localhost.mof'
    if (-not (Test-Path $mof)) { throw 'DSC compilation produced no localhost.mof' }

    $before = Test-DscConfiguration -ReferenceConfiguration $mof
    $after = $null
    $reboot = $false
    if ($Mode -ne 'audit') {
        & $LcmInitializer $WorkDir
        $dscErrors = @()
        Start-DscConfiguration -Path $mofDir -Wait -Force -ErrorAction Continue -ErrorVariable dscErrors | Out-Null
        foreach ($e in @($dscErrors)) { if ($e) { Write-Warning "DSC: $e" } }
        $reboot = [bool](Get-Variable -Name DSCMachineStatus -Scope Global -ValueOnly -ErrorAction SilentlyContinue)
        $after = Test-DscConfiguration -ReferenceConfiguration $mof
    }
    return @{ results = (ConvertTo-PatchgateDscEvidence -Before $before -After $after -Mode $Mode); rebootRequired = $reboot }
}

Export-ModuleMember -Function Initialize-PatchgateWinRm, Expand-PatchgateZip, Install-PatchgateModule, Get-PatchgateDscScript, ConvertTo-PatchgateDscEvidence, Invoke-PatchgateDscBaseline, Initialize-PatchgateLcm

'@

$installer = Join-Path $env:ProgramData 'Patchgate\bin\Install-PatchgatePlan.ps1'
$eventFile = Join-Path $env:ProgramData 'Patchgate\drift-event.json'
if (-not (Test-Path $installer)) { 'not bootstrapped by Patchgate; skipping'; exit 0 }
& $installer -Drift
$rc = $LASTEXITCODE
if (Test-Path $eventFile) {
  $token = Invoke-RestMethod -Method Put -Uri 'http://169.254.169.254/latest/api/token' -Headers @{ 'X-aws-ec2-metadata-token-ttl-seconds' = '60' }
  $h = @{ 'X-aws-ec2-metadata-token' = $token }
  $region = Invoke-RestMethod -Headers $h -Uri 'http://169.254.169.254/latest/meta-data/placement/region'
  $iid = Invoke-RestMethod -Headers $h -Uri 'http://169.254.169.254/latest/meta-data/instance-id'
  $detail = Get-Content -Raw -Path $eventFile | ConvertFrom-Json
  $detail | Add-Member -NotePropertyName instanceId -NotePropertyValue $iid -Force
  $detailJson = $detail | ConvertTo-Json -Depth 8 -Compress
  $published = $false
  $aws = (Get-Command aws.exe -ErrorAction SilentlyContinue).Source
  if (-not $aws -and (Test-Path 'C:\Program Files\Amazon\AWSCLIV2\aws.exe')) { $aws = 'C:\Program Files\Amazon\AWSCLIV2\aws.exe' }
  if ($aws) {
    $entries = '[' + (@{ Source = 'io.patchgate'; DetailType = 'Patchgate Drift Detected'; Detail = $detailJson } | ConvertTo-Json -Compress) + ']'
    $tmp = Join-Path $env:TEMP 'patchgate-entries.json'
    [IO.File]::WriteAllText($tmp, $entries, (New-Object Text.UTF8Encoding $false))
    $failed = & $aws events put-events --region $region --entries "file://$tmp" --query FailedEntryCount --output text
    $published = ($LASTEXITCODE -eq 0 -and "$failed".Trim() -eq '0')
    Remove-Item -Path $tmp -Force
  }
  elseif (Get-Command Write-EVBEvent -ErrorAction SilentlyContinue) {
    $entry = New-Object Amazon.EventBridge.Model.PutEventsRequestEntry
    $entry.Source = 'io.patchgate'; $entry.DetailType = 'Patchgate Drift Detected'; $entry.Detail = $detailJson
    $published = ((Write-EVBEvent -Entry $entry -Region $region).FailedEntryCount -eq 0)
  }
  if ($published) { Remove-Item -Path $eventFile -Force; 'drift event published' } else { Write-Warning 'failed to publish drift event' }
}
exit $rc
